import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    if n == 0 or m == 0:
        for _ in range(n):
            print()
        return

    matrix = []
    index = 2
    for i in range(n):
        row = list(map(int, data[index:index + m]))
        matrix.append(row)
        index += m

    # Find rows and columns that have zeros
    zero_rows = set()
    zero_cols = set()

    for i in range(n):
        for j in range(m):
            if matrix[i][j] == 0:
                zero_rows.add(i)
                zero_cols.add(j)

    # Build the result matrix
    result = []
    for i in range(n):
        row = []
        for j in range(m):
            if i in zero_rows or j in zero_cols:
                row.append(0)
            else:
                row.append(matrix[i][j])
        result.append(row)

    # Print the result
    for row in result:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()
